/// <summary>
/// MPJ_11539 - kscerri - 08/04/2021
/// Header tmp table
/// </summary>
/// <returns>tmp table</returns>
[SRSReportDataSetAttribute(tablestr(METTransferOrderLoadPlanningAidHeaderTmp))]
public METTransferOrderLoadPlanningAidHeaderTmp getHeader()
{
    select transferOrderLoadPlanningAidHeaderTmp;
    return transferOrderLoadPlanningAidHeaderTmp;
}

/// <summary>
/// MPJ_11539 - kscerri - 08/04/2021
/// Invoice lines tmp table
/// </summary>
/// <returns>tmp table</returns>
[SRSReportDataSetAttribute(tablestr(METTransferOrderLoadPlanningAidLinesTmp))]
public METTransferOrderLoadPlanningAidLinesTmp getLines()
{
    select transferOrderLoadPlanningAidLinesTmp;
    return transferOrderLoadPlanningAidLinesTmp;
}

public void processReport()
{
    contract = this.parmDataContract() as METTransferOrderLoadPlanningAidContract;
    METRoute routeId = contract.parmRouteID();
    SalesShippingDateConfirmed confirmedShipDateFrom = contract.parmConfirmedShipDateFrom();
    SalesShippingDateRequested confirmedShipDateTo = contract.parmConfirmedShipDateTo();

    InventLocationId           inventLocationTo = contract.parmInventLocationTo();
    InventLocationId           inventLocationFrom = contract.parmInventLocationFrom();
    boolean                    usePrintManagement = contract.parmUsePrintManagement();

    Query transferOrderLoadPlanningAid = new Query(queryStr(METTransferOrderLoadPlanningAid));


    transferOrderLoadPlanningAid.dataSourceName(queryDataSourceStr(METTransferOrderLoadPlanningAid, InventTransferTable)).rangeField(
                fieldNum(InventTransferTable, InventLocationIdFrom)).value(SysQuery::value(confirmedShipDateFrom));

    transferOrderLoadPlanningAid.dataSourceName(queryDataSourceStr(METTransferOrderLoadPlanningAid, InventTransferTable)).rangeField(
                fieldNum(InventTransferTable, InventLocationIdFrom)).value(SysQuery::value(confirmedShipDateTo));

    if (inventLocationFrom)
    {
        transferOrderLoadPlanningAid.dataSourceName(queryDataSourceStr(METTransferOrderLoadPlanningAid, InventTransferTable)).rangeField(
                fieldNum(InventTransferTable, InventLocationIdFrom)).value(SysQuery::value(inventLocationFrom));
    }

    if (inventLocationTo)
    {
        transferOrderLoadPlanningAid.dataSourceName(queryDataSourceStr(METTransferOrderLoadPlanningAid, InventTransferTable)).rangeField(
                fieldNum(InventTransferTable, InventLocationIdTo)).value(SysQuery::value(inventLocationTo));
    }

    if (routeId)
    {
        transferOrderLoadPlanningAid.dataSourceName(queryDataSourceStr(METTransferOrderLoadPlanningAid, METInventTransferTableExt)).rangeField(
            fieldNum(METInventTransferTableExt, RouteStopNum)).value(SysQuery::value(routeId));
    }

    //QueryRun queryRun = new QueryRun(transferOrderLoadPlanningAid);

    InventTransferTable inventTransferTable;
    InventTransferLine  inventTransferLine;
    METInventTransferTableExt metInventTransferTableExt;
    METInventTransferLine   metInventTransferLine;
    MetInventItemOrderSetup metInventItemOrderSetup;
    ReqItemTable reqItemTable;
    MetReqItemTable metReqItemTable;
    InventDim               inventDim;
    InventDim   inventDimReq;
    InventLocation          inventLocation;
    METInventLocation       metInventLocation;
    Map                     insertRecordsetMap = new Map(Types::String,Types::Container);
    QueryBuildDataSource    qbds;
    QueryBuildFieldList     qbfl;
    int                     dataSourceUniqueId;
    QueryBuildRange         qbr;

    qbds = transferOrderLoadPlanningAid.dataSourceTable(tableNum(METInventTransferTableExt));
    qbfl = qbds.fields();
    dataSourceUniqueId = qbds.uniqueId();
    //this.addInsertFieldMapping(qbfl, insertRecordsetMap, dataSourceUniqueId, fieldNum(METInventTransferTableExt, RouteStopNum), fieldStr(METInventTransferTableExt, RouteStopNum), fieldStr(METTransferOrderLoadPlanningAidLinesTmp, StopNumber));


    //while (queryRun.next())
    //{
    //    inventTransferTable = queryRun.get(tableNum(inventTransferTable));
    //    inventTransferLine = queryRun.get(tableNum(InventTransferLine));
    //    metInventTransferTableExt = queryRun.get(tableNum(METInventTransferTableExt));
    //    metInventTransferLine = queryRun.get(tableNum(METInventTransferLine));

    //    inventLocation = queryRun.get(tableNum(InventLocation));
    //    metInventLocation = queryRun.get(tableNum(METInventLocation));




    //}


    //insert_recordset transferOrderLoadPlanningAidLinesTmp(Cases, Eaches, Weight, Cube)
    //    select Cases, BrokenCase, TotalWeight, TotalVolume from metInventTransferLine
    //    group by metInventTransferLine.Cases, metInventTransferLine.BrokenCase
    //    join inventTransferLine
    //        where metInventTransferLine.InventTransferLine == inventTransferLine.RecId
    //    join inventTransferTable
    //        where inventTransferTable.TransferId == inventTransferLine.TransferId
    //        && inventTransferTable.TransferStatus == InventTransferStatus::Created
    //        && (!inventLocationFrom  || inventTransferTable.InventLocationIdFrom == inventLocationFrom)
    //        && (!inventLocationTo  || inventTransferTable.InventLocationIdTo == inventLocationTo)
    //        && (inventTransferTable.ShipDate >=  confirmedShipDateFrom && inventTransferTable.ShipDate <=  confirmedShipDateTo)
    //    join metInventTransferTableExt
    //        where metInventTransferTableExt.InventTransferTable == inventTransferTable.RecId
    //        && (!routeId  || metInventTransferTableExt.Route == routeId)
    //    join inventDim
    //    where inventDim.inventDimId == inventTransferLine.InventDimId;

    insert_recordset transferOrderLoadPlanningAidLinesTmp(TransferId, LineRecId)
        select TransferId, RecId from inventTransferLine
        join inventTransferTable
            where inventTransferTable.TransferId == inventTransferLine.TransferId
            //&& inventTransferTable.TransferStatus == InventTransferStatus::Created
            && (!inventLocationFrom  || inventTransferTable.InventLocationIdFrom == inventLocationFrom)
            && (!inventLocationTo  || inventTransferTable.InventLocationIdTo == inventLocationTo)
            && (inventTransferTable.ShipDate >=  confirmedShipDateFrom && inventTransferTable.ShipDate <=  confirmedShipDateTo)
        join metInventTransferTableExt
            where metInventTransferTableExt.InventTransferTable == inventTransferTable.RecId
            && (!routeId  || metInventTransferTableExt.Route == routeId)
        join inventDim
        where inventDim.inventDimId == inventTransferLine.InventDimId;

    //update_recordset transferOrderLoadPlanningAidLinesTmp
    //    setting HeaderRecId = inventTransferTable.RecId,
    //    OrderDateTIme = inventTransferTable.CreatedDateTime,
    //    InventLocationIdFrom = inventTransferTable.InventLocationIdFrom,
    //    StopNumber = metInventTransferTableExt.RouteStopNum,
    //    Pallets = metInventLocation.WHSPalletVolume
    //    join inventTransferTable
    //        where inventTransferTable.TransferId == transferOrderLoadPlanningAidLinesTmp.TransferId
    //    join metInventTransferTableExt
    //        where metInventTransferTableExt.InventTransferTable == transferOrderLoadPlanningAidLinesTmp.HeaderRecId
    //    join inventLocation
    //        where inventLocation.InventLocationId == inventTransferTable.InventLocationIdFrom
    //    join metInventLocation
    //        where metInventLocation.InventLocation == inventLocation.RecId;

    //update_recordset transferOrderLoadPlanningAidLinesTmp
    //    setting StopNumber = metInventTransferTableExt.RouteStopNum
    //    join metInventTransferTableExt
    //    where metInventTransferTableExt.InventTransferTable == transferOrderLoadPlanningAidLinesTmp.HeaderRecId;


    update_recordset transferOrderLoadPlanningAidLinesTmp
        setting Cases = metInventTransferLine.Cases,
        Eaches = metInventTransferLine.BrokenCase,
        Weight = metInventTransferLine.TotalWeight,
        Cube = metInventTransferLine.TotalVolume
        join metInventTransferLine
            where metInventTransferLine.InventTransferLine == transferOrderLoadPlanningAidLinesTmp.LineRecId;

    //update_recordset transferOrderLoadPlanningAidLinesTmp
    //    setting StopNumber = metInventTransferTableExt.RouteStopNum
    //    join metInventTransferTableExt
    //    where metInventTransferTableExt.InventTransferTable == transferOrderLoadPlanningAidLinesTmp.HeaderRecId;


    //update_recordset transferOrderLoadPlanningAidLinesTmp
    //    setting ToWarehouseNumber = metInventLocation
    //    join metInventLocation
    //    where metInventLocation.InventTransferTable == transferOrderLoadPlanningAidLinesTmp.HeaderRecId;


    update_recordset transferOrderLoadPlanningAidLinesTmp
        setting OrderSplitCategoryCode = metReqItemTable.OSCCode
    join RecId from inventTransferLine
         where inventTransferLine.TransferId == transferOrderLoadPlanningAidLinesTmp.TransferId
        && inventTransferLine.LineNum == transferOrderLoadPlanningAidLinesTmp.LineNum
   join RecId from inventDim
        where inventDim.inventDimId == inventTransferLine.InventDimId
    join ItemType from metInventItemOrderSetup
        where metInventItemOrderSetup.ItemId == inventTransferLine.ItemId
        &&  metInventItemOrderSetup.SiteId == inventDim.InventSiteId
    join Recid from reqItemTable
        where reqItemTable.ItemId == inventTransferLine.ItemId
    join OSCCode from metReqItemTable
        where metReqItemTable.RefRecId == reqItemTable.RecId
     exists join inventDimReq
        where inventDimReq.InventSiteId == inventDim.InventSiteId
        && InventDimReq.InventLocationId == inventDim.InventLocationId
        && inventDimReq.inventDimId == reqItemTable.CovInventDimId;




    while select inventTransferLine
        join inventTransferTable
            where inventTransferTable.TransferId == inventTransferLine.TransferId
        && inventTransferTable.ShipDate == confirmedShipDateFrom
        join metInventTransferTableExt
            where metInventTransferTableExt.InventTransferTable == inventTransferTable.RecId
            && metInventTransferTableExt.Route == routeId
        join inventDim
            where inventDim.inventDimId == inventTransferLine.InventDimId
    {


       //     update_recordset metExtractScreenTmp
       //     setting OSCCode = metReqItemTable.OSCCode
       // join RecId from inventTransferLine
       //      where inventTransferLine.TransferId == metExtractScreenTmp.TransferId
       //     && inventTransferLine.LineNum == metExtractScreenTmp.LineNum
       //join RecId from inventDim
       //     where inventDim.inventDimId == inventTransferLine.InventDimId
       // join ItemType from metInventItemOrderSetup
       //     where metInventItemOrderSetup.ItemId == inventTransferLine.ItemId
       //     &&  metInventItemOrderSetup.SiteId == inventDim.InventSiteId
       //     &&  metInventItemOrderSetup.FilterCode == metExtractScreenTmp.FilterCodeOne
       // join Recid from reqItemTable
       //     where reqItemTable.ItemId == inventTransferLine.ItemId
       // join OSCCode from metReqItemTable
       //     where metReqItemTable.RefRecId == reqItemTable.RecId
       //  exists join inventDimReq
       //     where inventDimReq.InventSiteId == inventDim.InventSiteId
       //     && InventDimReq.InventLocationId == inventDim.InventLocationId
       //     && inventDimReq.inventDimId == reqItemTable.CovInventDimId;
    }



}

/// <summary>
/// Set the database transaction connection for a record from the connection associated with the report.
/// </summary>
/// <param name = "_reportRecord">
/// A record to set database transaction for.
/// </param>
final protected void setTransactionConnection(Common _reportRecord)
{
    var connection = this.parmUserConnection();

    if (connection)
    {
        _reportRecord.setConnection(connection);
    }
}

private void addInsertFieldMapping(QueryBuildFieldList _fieldList, Map _fieldMapping, int _sourceTableUniqueId, FieldId _sourceFieldId, FieldName _sourceFieldName, FieldName _destinationFieldName)
{
    _fieldList.addField(_sourceFieldId);
    _fieldMapping.insert(_destinationFieldName, [_sourceTableUniqueId, _sourceFieldName]);
}
